<script>
 import {onMount} from 'svelte';import {X,Check,ChevronLeft,ChevronRight} from 'lucide-svelte';import {studio,asset,run,updateProject,thumbnails,notify,clearDrafts,confirmReplace} from '../studio.svelte';import {api,imageUrl,clone} from '../api';import {money} from '../cost';
 let dialog,after=$state(''),before=$state(''),metadata=$state(null),split=$state(50);const modal=studio.modal;
 onMount(()=>{dialog.showModal();let urls=[];Promise.all([imageUrl('generated_preview',{projectId:studio.pid,assetId:studio.aid,versionId:modal.version.id}),imageUrl('original_preview',{projectId:studio.pid,assetId:studio.aid}),api('generation_details',{projectId:studio.pid,assetId:studio.aid,versionId:modal.version.id}).catch(()=>null)]).then(([a,b,m])=>{after=a;before=b;metadata=m;urls=[a,b];}).catch(e=>studio.error=e.message);return()=>urls.forEach(URL.revokeObjectURL);});
 async function adopt(){if(studio.confirm)return;await confirmReplace("采用此版本？",()=>run("正在采用版本",async()=>{const p=await api('adopt_generated',{projectId:studio.pid,assetId:studio.aid,versionId:modal.version.id});updateProject(p);clearDrafts([studio.aid]);studio.draft=clone(asset().edit);studio.history[studio.aid]=[];studio.redo[studio.aid]=[];await thumbnails(undefined,true);studio.modal='';studio.mode='edit';notify("已采用此版本");}));}
</script>
<dialog bind:this={dialog} class="review-dialog" onclose={()=>studio.modal=''}><div class="dialog-heading"><h2>查看此版本</h2><button aria-label="关闭预览" onclick={()=>studio.modal=''}><X size={19}/></button></div><div class="review-image"><img src={after} alt="生成结果"/><div class="compare-before" style:clip-path={`inset(0 ${100-split}% 0 0)`}><img src={before} alt="原图"/></div><div class="compare-line" style:left={`${split}%`}><span><ChevronLeft size={12}/><ChevronRight size={12}/></span></div><input class="compare-slider" aria-label="对比生成结果" type="range" min="0" max="100" bind:value={split}/><span class="compare-label before">原图</span><span class="compare-label after">新版本</span></div>{#if metadata}<div class="review-meta"><span>{metadata.model||modal.version.kind}</span><span>{metadata.costBounds?`${money(metadata.costBounds.minimumUsd,studio.currency,studio.exchangeRate)} – ${money(metadata.costBounds.maximumUsd,studio.currency,studio.exchangeRate)}`:metadata.actualUsd!=null?money(metadata.actualUsd,studio.currency,studio.exchangeRate):''}</span></div>{/if}<div class="dialog-actions"><button class="line-button" onclick={()=>studio.modal=''}>暂不采用</button><button class="primary" onclick={adopt} disabled={!!studio.busy||!after}><Check size={15}/>采用并编辑</button></div></dialog>
